// Block Storage: Random access using FileChannel
RandomAccessFile raf = new RandomAccessFile("data.bin", "rw");
FileChannel channel = raf.getChannel();
ByteBuffer buffer = ByteBuffer.allocate(1024);
channel.read(buffer, 4096); // Seek and read at specific offset

// Object Storage: SDK approach (AWS S3)
S3Client s3 = S3Client.builder().build();
PutObjectRequest request = PutObjectRequest.builder().bucket("my-bucket").key("file.txt").build();
s3.putObject(request, RequestBody.fromFile(Paths.get("local.txt")));
